package com.pridesys.ticketing.client.controller;import com.pridesys.ticketing.dto.*;import com.pridesys.ticketing.entity.*;import com.pridesys.ticketing.repository.ClientRepository;import com.pridesys.ticketing.repository.UserRepository;import com.pridesys.ticketing.security.util.JwtService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import java.util.*;
@RestController@RequestMapping("/api/clients")public class ClientController{private final ClientRepository clients;private final UserRepository users;public ClientController(ClientRepository c,UserRepository u){clients=c;users=u;}private void admin(Authentication a){var u=users.findById(((JwtService.UserPrincipal)a.getPrincipal()).id()).orElseThrow();if(u.getRole()!=UserRole.APP_ADMIN)throw new org.springframework.security.access.AccessDeniedException("APP_ADMIN required");}@GetMapping public List<ClientRecord> list(Authentication a){admin(a);return clients.findAll().stream().map(c->new ClientRecord(c.getId(),c.getName(),c.isActive())).toList();}@PostMapping public ClientRecord create(Authentication a,@Valid@RequestBody UsersProjectsDtos.CreateClientRequest r){admin(a);var c=clients.save(new ClientEntity(r.name().trim()));return new ClientRecord(c.getId(),c.getName(),c.isActive());}}
